// The short reference a customer quotes for a quote request (F-021).
//
// There is no reference column on `inquiries` and the requester is anonymous
// (RLS lets them insert but not read the row back), so the id is generated by
// the route and the reference is derived from it: "Q-" + the first 8 hex digits
// of the uuid, upper case. Stable (same id, same reference), easy to read out
// over WhatsApp, and the owner can find the row with `id::text like 'xxxxxxxx%'`.
// The reference is also written into the stored message so a lead that was only
// emailed (database write failed) can still be matched.

const PREFIX = "Q-";

/** "3f2a91c4-…" -> "Q-3F2A91C4". Null for anything that is not a uuid. */
export function quoteReference(id: string): string | null {
  const m = /^([0-9a-f]{8})-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.exec(id.trim());
  return m ? `${PREFIX}${m[1].toUpperCase()}` : null;
}
